            const paths = event.files.map((f) => f.path);
            const filePath = paths.length === 1 ? paths[0] : `${paths.length} files`;
            const summary = event.files.map((f) => `${f.kind}: ${f.path}`).join('\n');
            const resultCard: ToolResultCard = {
              toolUseId: event.changeId,
              toolName: 'Edit',
