    24	export interface CodexSessionSummary {
    25	  /** Codex thread id — the value passed to `codex exec resume <id>`. */
    26	  id: string;
    27	  /** Working directory recorded in the rollout, when Codex wrote one. */
    28	  cwd?: string;
    29	  /** First user prompt, trimmed — used as the list preview. */
    30	  preview: string;
    31	  /** Number of JSONL lines in the rollout. */
    32	  messageCount: number;
    33	  /** File mtime in ms since epoch. */
