    37	/** Rollout line types we keep; everything else is preamble/usage/encrypted noise. */
    38	const KEPT = `new Set([
    39	  'event_msg:user_message',
    40	  'event_msg:agent_message',
    41	  'response_item:function_call',
    42	  'response_item:function_call_output',
    43	  'response_item:custom_tool_call',
    44	  'response_item:custom_tool_call_output',
    45	  'response_item:web_search_call',
    46	])`;
    47	
    48	const LIST_SCRIPT = String.raw`
    49	const fs = require('fs'), os = require('os'), path = require('path');
    50	const root = path.join(os.homedir(), '.codex', 'sessions');
    51	const out = [];
    52	const UUID_RE = /([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})\.jsonl$/;
    53	function walk(dir) {
    54	  let entries;
    55	  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    56	  for (const e of entries) {
    57	    const full = path.join(dir, e.name);
    58	    if (e.isDirectory()) walk(full);
    59	    else if (e.name.startsWith('rollout-') && e.name.endsWith('.jsonl')) readRollout(full, e.name);
    60	  }
    61	}
    62	function findString(value, keys) {
    63	  if (!value || typeof value !== 'object') return null;
    64	  if (Array.isArray(value)) {
    65	    for (const item of value) {
    66	      const hit = findString(item, keys);
    67	      if (hit) return hit;
    68	    }
    69	    return null;
    70	  }
    71	  for (const key of keys) {
    72	    if (typeof value[key] === 'string' && value[key]) return value[key];
    73	  }
    74	  for (const key of Object.keys(value)) {
    75	    const hit = findString(value[key], keys);
    76	    if (hit) return hit;
    77	  }
    78	  return null;
    79	}
    80	function userPreview(o) {
    81	  const p = o && o.payload;
    82	  if (o && o.type === 'event_msg' && p && p.type === 'user_message') {
    83	    if (typeof p.message === 'string') return p.message;
    84	    return findString(p.message, ['text', 'content']) || '';
    85	  }
    86	  if (o && (o.type === 'user_message' || o.type === 'user')) {
    87	    return findString(o, ['message', 'text', 'content']) || '';
    88	  }
    89	  return '';
    90	}
    91	function threadId(o) {
    92	  const p = o && o.payload;
    93	  return findString(o, ['thread_id', 'threadId']) || (p && findString(p, ['thread_id', 'threadId'])) || null;
    94	}
    95	function fileId(name) {
    96	  const uuid = name.match(UUID_RE);
    97	  if (uuid) return uuid[1];
    98	  return name.replace(/^rollout-/, '').replace(/\.jsonl$/, '').split('-').pop();
    99	}
   100	function readRollout(fp, name) {
   101	  let stat, content;
   102	  try { stat = fs.statSync(fp); content = fs.readFileSync(fp, 'utf8'); } catch { return; }
   103	  const lines = content.split('\n').filter((l) => l.trim());
   104	  if (lines.length === 0) return;
   105	  let id = fileId(name);
   106	  let cwd = null;
   107	  let preview = '';
   108	  for (const line of lines) {
   109	    let o;
   110	    try { o = JSON.parse(line); } catch { continue; }
   111	    if (!id) id = threadId(o);
   112	    if (!cwd) cwd = findString(o, ['cwd', 'working_directory', 'workingDirectory']);
   113	    if (!preview) preview = userPreview(o);
   114	    if (id && cwd && preview) break;
   115	  }
   116	  if (!id) return;
   117	  out.push({
   118	    id,
   119	    cwd,
   120	    preview: (preview || '').slice(0, 240),
   121	    messageCount: lines.length,
   122	    modified: Math.floor(stat.mtimeMs),
   123	  });
   124	}
   125	try { walk(root); } catch (e) {}
   126	out.sort((a, b) => b.modified - a.modified);
   127	process.stdout.write('@@WISP@@' + JSON.stringify(out) + '@@WISP@@');
   128	`;
