   130	/**
   131	 * Node script (run on the sprite) that locates the rollout for a thread id and
   132	 * re-emits only the relevant lines between sentinel markers, so we transfer a
   133	 * few KB rather than the multi-MB raw file. The id is inlined as a JS string
   134	 * literal; callers must validate it against SESSION_ID_RE first.
   135	 */
   136	function readScript(sessionId: string): string {
   137	  return String.raw`
   138	const fs = require('fs'), os = require('os'), path = require('path');
   139	const ID = ${JSON.stringify(sessionId)};
   140	const root = path.join(os.homedir(), '.codex', 'sessions');
   141	const KEPT = ${KEPT};
   142	function find(dir) {
   143	  let entries;
   144	  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return null; }
   145	  for (const e of entries) {
   146	    const full = path.join(dir, e.name);
   147	    if (e.isDirectory()) { const hit = find(full); if (hit) return hit; }
   148	    else if (e.name.startsWith('rollout-') && e.name.endsWith('.jsonl') && e.name.includes(ID)) {
   149	      return full;
   150	    }
   151	  }
   152	  return null;
   153	}
   154	const out = [];
   155	try {
   156	  const fp = find(root);
   157	  if (fp) {
   158	    const content = fs.readFileSync(fp, 'utf8');
   159	    const CAP = 4000;
   160	    for (const line of content.split('\n')) {
   161	      if (!line.trim()) continue;
   162	      let o; try { o = JSON.parse(line); } catch { continue; }
   163	      const p = o && o.payload;
   164	      const key = o && o.type + ':' + (p && p.type);
   165	      if (!key || !KEPT.has(key)) continue;
   166	      // Cap large command outputs so a transcript sync stays a few hundred KB.
   167	      if (p && typeof p.output === 'string' && p.output.length > CAP) {
   168	        p.output = p.output.slice(0, CAP) + '\n…[truncated]';
   169	        out.push(JSON.stringify(o));
   170	      } else {
   171	        out.push(line);
   172	      }
   173	    }
   174	  }
   175	} catch (e) {}
   176	process.stdout.write('@@WISP@@' + out.join('\n') + '@@WISP@@');
   177	`;
   178	}
   179	
   180	function heredoc(script: string): string {
